questionvariables.text:
/*
Shared Question Bank
Place Value, Rounding and Standard Form
PVRS-03

Procedural task:
round a decimal to a specified decimal
place using half-up rounding.
*/


/*
1 = nearest tenth
2 = nearest hundredth
*/

place_choice:
    rand_with_prohib(1,2,[]);

scale:
    if place_choice=1 then 10
    else 100;

place_name:
    if place_choice=1 then "tenth"
    else "hundredth";


/*
Generate a positive decimal with enough
digits to make the rounding decision useful.
*/

whole_part:
    rand_with_prohib(1,99,[]);

tenths_digit:
    rand_with_prohib(0,9,[]);

hundredths_digit:
    rand_with_prohib(0,9,[]);

thousandths_digit:
    rand_with_prohib(5,9,[]);


/*
For nearest tenth, force the hundredths
digit to be at least 5.

For nearest hundredth, force the
thousandths digit to be at least 5.

This guarantees truncation differs from
correct rounding.
*/

effective_hundredths:
    if place_choice=1
    then rand_with_prohib(5,9,[])
    else hundredths_digit;


number:
    whole_part
    + tenths_digit/10
    + effective_hundredths/100
    + thousandths_digit/1000;


/*
Explicit half-up rounding.
*/

answer:
    floor(
        number*scale + 1/2
    )/scale;


/*
Target misconception:
truncate at the requested decimal place.
*/

wrong_truncate:
    floor(number*scale)/scale;


/*
Display decimal forms while retaining
exact rational values internally for
grading.
*/

number_display:
    float(number);

answer_display:
    float(answer);

wrong_truncate_display:
    float(wrong_truncate);
